                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.ean_to_sku_mapping as select ean, sku from SNITCH_DB.MAPLEMONK.LOGIC_FINAL_ITEM_MASTER ; CREATE OR REPLACE TABLE snitch_db.maplemonk.logic_final_sto AS WITH ranked_stock_transfer_out AS ( SELECT h.*, ROW_NUMBER() OVER ( PARTITION BY h.NEW_BILL_NO ORDER BY TO_TIMESTAMP(h.bill_time, \'DD/MM/YYYY HH12:MI AM\') DESC ) AS rn_bill, ROW_NUMBER() OVER ( PARTITION BY h.ORDER_NO ORDER BY TO_TIMESTAMP(h.bill_time, \'DD/MM/YYYY HH12:MI AM\') DESC ) AS rn_order FROM snitch_db.maplemonk.logicstream_get_stock_transfer_out h ), filtered_stock_transfer_out AS ( SELECT * FROM ranked_stock_transfer_out WHERE rn_bill = 1 AND rn_order = 1 ), final_stock_transfer_out_lines AS ( SELECT f.bill_date, CASE WHEN f.account_name like \'%SNITCH X%\' THEN \'SNITCH - X\' ELSE TRIM(RTRIM(REGEXP_SUBSTR(f.account_name, \'^[^-]*-[^-]*-[^-]*\', 1, 1), \'-\')) END AS to_party, CASE WHEN f.account_name like \'%SNITCH X%\' THEN \'SNITCH - X\' ELSE TRIM(RTRIM(REGEXP_SUBSTR(f.branch_name, \'^[^-]*-[^-]*-[^-]*\', 1, 1), \'-\')) END AS from_party, f.BILL_NO, f.ORDER_NO, f.QUANTITY AS TOTAL_QUANTITY, f.BILL_TIME AS BILL_TIME, f.DOC_NUMBER, f.NET_AMOUNT, f.ORDER_DATE, f.TRANS_NAME, f.VOUCH_CODE, f.NEW_BILL_NO, f.SO_ORDER_NO, f.ACCOUNT_CODE, f.CUSTOMER_CODE, f.CUSTOMER_NAME, f.BRANCH_SHORT_NAME, f.TYPE AS other_type, f.CASES, f.DD_CHQ, i.value:\"LogicUser_Code\"::STRING AS EAN, CASE WHEN UPPER(i.value:\"AddlItemCode\"::STRING ) like \'4C%\' then UPPER(i.value:\"AddlItemCode\"::STRING ) WHEN UPPER(UPPER(i.value:\"AddlItemCode\"::STRING )) LIKE \'%T-SHIRT%\' OR UPPER(UPPER(i.value:\"AddlItemCode\"::STRING )) LIKE \'%CO-ORDS%\' THEN replace(replace(UPPER(UPPER(i.value:\"AddlItemCode\"::STRING )),\'T-SHIRT-\',\'\'),\'CO-ORDS-\',\'\') WHEN REGEXP_COUNT(UPPER(i.value:\"AddlItemCode\"::STRING ), \'-\') = 3 THEN SPLIT_PART(UPPER(i.value:\"AddlItemCode\"::STRING ), \'-\', 1)||\'-\'|| SPLIT_PART(UPPER(i.value:\"AddlItemCode\"::STRING ), \'-\', 2)||\'-\'||SPLIT_PART(UPPER(i.value:\"AddlItemCode\"::STRING ), \'-\', 4) ELSE UPPER(i.value:\"AddlItemCode\"::STRING ) END AS SKU_DUMMY, i.value:\"Quantity\"::FLOAT AS ITEM_QUANTITY, i.value:\"ItemName\"::STRING AS ITEMNAME, i.value:\"Item_Group_Name_1\"::STRING AS ITEM_GROUP_NAME_1, i.value:\"Item_MRP\"::FLOAT AS ITEM_MRP, i.value:\"Item_Sale_Rate\"::FLOAT AS ITEM_SALE_RATE, i.value:\"Tax_1\"::FLOAT AS TAX_1, i.value:\"Tax_2\"::FLOAT AS TAX_2, i.value:\"Tax_3\"::FLOAT AS TAX_3, i.value:\"Sale_Amt\"::FLOAT AS SALE_AMT FROM filtered_stock_transfer_out f, LATERAL FLATTEN(input => f.LSTITEMS) i ), final AS ( SELECT \'STO\' AS TYPE, CASE WHEN ( to_party like \'%WH - EM%\' or to_party like \'%WH - YE%\' or to_party like \'%WH - NOR%\' ) and ( from_party like \'%WH - EM%\' or from_party like \'%WH - YE%\' or from_party like \'%WH - NOR%\' ) then \'WH-WH\' WHEN to_party like \'%SURAT-VR MALL%\' or from_party like \'%SURAT-VR MALL%\' THEN \'TEST\' WHEN from_party like \'%SNITCH - WH%\' and (to_party like \'%SNITCH - WH - YE%\' or to_party like \'%SNITCH - WH - EMIZ%\' or to_party like \'%SNITCH - WH - NORTH%\') THEN \'VIRTUAL-WH\' WHEN from_party LIKe \'%SNITCH - HO%\' THEN \'HO-WH\' WHEN to_party ILIKE \'%SNITCH - HO%\' THEN \'WH-HO\' WHEN from_party LIKe \'%WH - B2B%\' THEN \'B2B-WH\' WHEN to_party ILIKE \'%WH - B2B%\' THEN \'WH-B2B\' WHEN to_party ILIKE \'%SLIKK%\' THEN \'WH-SLIKK\' WHEN from_party ILIKE \'%SLIKK%\' THEN \'SLIKK-WH\' WHEN to_party ILIKE \'%MYNTRA SJIT%\' THEN \'WH-SJIT\' WHEN from_party ILIKE \'%MYNTRA SJIT%\' THEN \'SJIT-WH\' WHEN to_party ILIKE \'%SNITCH - KNOT%\' THEN \'WH-KNOT\' WHEN from_party ILIKE \'%SNITCH - KNOT%\' THEN \'KNOT-WH\' WHEN (to_party ILIKE \'%CO%\' OR to_party ILIKE \'%FO%\') AND (from_party ILIKE \'%CO%\' OR from_party ILIKE \'%FO%\') THEN \'STORE-STORE\' WHEN (TO_PARTY like \'%CO%\' or TO_PARTY LIKE \'%FO%\') and FROM_PARTY not like \'%YEL%\' and FROM_PARTY not like \'%EMIZA%\' and from_party not like \'%WH - NORTH%\' THEN \'VIRTUAL-STORE\' WHEN (from_party ILIKE \'%SNITCH - WH - YE%\' OR from_party ILIKE \'%SNITCH - WH - EM%\' OR from_party ILIKE \'%SNITCH - WH - NORT%\') AND (to_party NOT ILIKE \'%YELHA%\' and to_party not ilike \'%WH-NORTH%\' AND to_party NOT ILIKE \'%EMIZA%\'and to_party like \'%WH -%\') THEN \'WH-VIRTUAL\' WHEN (from_party ILIKE \'%SNITCH - WH - YE%\' OR from_party ILIKE \'%SNITCH - WH - EM%\'OR from_party ILIKE \'%SNITCH - WH - NORTH%\') AND (to_party NOT ILIKE \'%YELHA%\' AND to_party NOT ILIKE \'%EMIZA%\' and to_party not ilike \'%WH-NORTH%\') THEN \'WH-STORE\' WHEN (to_party ILIKE \'%SNITCH - WH - YE%\' OR to_party ILIKE \'%SNITCH - WH - EM%\' and to_party ilike \'%WH-NORTH%\') AND (from_party ILIKE \'%CO%\' OR from_party ILIKE \'%FO%\' OR from_party ILIKE \'%WHI%\') THEN \'STORE-WH\' WHEN from_party like \'%YEL%\' or from_party like \'%EMIZA%\' then \'WH-OTHERS\' WHEN to_party like \'%YEL%\' or to_party like \'%EMIZA%\' then \'OTHERS-WH\' WHEN to_party like \'%CO%\' or to_party like \'%FO%\' then \'OTHERS-STORE\' WHEN from_party like \'%CO%\' or from_party like \'%FO%\' then \'STORE-OTHERS\' ELSE \'OTHERS\' END AS ORIGIN , * FROM final_stock_transfer_out_lines ), draft1 as ( SELECT * FROM final where new_bill_no not in (\'2425/9/ST-1510\',\'2425/9/ST-1507\',\'2425/8/ST-5330\',\'2425/8/ST-5330\', \'2425/9/ST-2515\', \'2425/9/ST-2517\', \'2425/9/ST-2516\', \'2425/9/ST-2518\',\'2526/8/ST-2444\',\'2526/8/ST-3065\',\'2526/8/ST-3064\',\'2526/8/ST-3063\',\'2526/8/ST-3062\',\'2526/8/ST-5740\',\'2526/8/ST-5636\', \'2526/9/WS-1809\', \'2526/9/WS-1812\' ) ) select CASE WHEN d.sku_dummy like \'8%\' THEN e1.sku ELSE d.sku_dummy END AS SKU, d.* from draft1 d left join snitch_db.maplemonk.ean_to_sku_mapping e1 on d.sku_dummy = e1.ean ; create or replace table snitch_db.maplemonk.logic_final_sti as WITH FINAL AS ( SELECT \'STI\' AS TYPE, CASE WHEN BRANCH_NAME LIKE \'%SNITCH - HO%\' THEN \'WH-HO\' WHEN BRANCH_NAME LIKE \'%B2B%\' THEN \'WH-B2B\' WHEN ACCOUNT_NAME LIKE \'%B2B%\' THEN \'B2B-WH\' WHEN (branch_name like \'%SNITCH - WH - YE%\' or branch_name like \'%SNITCH - WH - EMI%\' or branch_name like \'%SNITCH - WH - NORTH%\') and (account_name like \'%SNITCH - WH - YE%\' or account_name like \'%SNITCH - WH - EMI%\' or account_name like \'%SNITCH - WH - NORTH%\') then \'WH-WH\' WHEN (BRANCH_NAME like \'%- WH - YE%\' OR BRANCH_NAME like \'%- WH - EM%\' or branch_name ilike \'%WH - NORTH%\') and account_name like \'%SNITCH - WH - %\' THEN \'VIRTUAL-WH\' WHEN (ACCOUNT_NAME like \'%- WH - YE%\' OR ACCOUNT_NAME like \'%- WH - EM%\' or account_name ilike \'%WH - NORTH%\') and BRANCH_NAME like \'%SNITCH - WH - %\' THEN \'WH-VIRTUAL\' when branch_name like \'%MYNTRA SJIT%\' then \'WH-MYNTRA_SJIT\' WHEN BRANCH_NAME LIKE \'%SLIKK%\' THEN \'WH-SLIKK\' WHEN ACCOUNT_NAME LIKE \'%SLIKK%\' THEN \'SLIKK-WH\' WHEN account_name like \'%WH UP%\' and account_name not like \'%YEL%\' and account_name not like \'%EMIZA%\' and account_name not ilike \'%WH - NORTH%\' and branch_name like \'SNITCH - FO%\' THEN \'VIRTUAL-STORE\' WHEN account_name like \'%SNITCH - WH%\' and account_name not like \'%YEL%\' and account_name not like \'%EMIZA%\' and account_name not ilike \'%WH - NORTH%\' and branch_name like \'SNITCH - FO%\' THEN \'VIRTUAL-STORE\' WHEN branch_name LIKE \'%SNITCH - WH%\' AND (account_name LIKE \'%SNITCH - WH - YE%\' OR account_name ilike \'%WH - NORTH%\' or account_name LIKE \'%SNITCH - WH - EM%\') THEN \'STORE-WH\' WHEN branch_name LIKE \'%SNITCH - WH%\' THEN \'NOTFOUND-WH\' WHEN (branch_name LIKE \'%COCO%\' OR branch_name LIKE \'%FOCO%\' OR branch_name LIKE \'%COFO%\' OR branch_name LIKE \'%JAYAN%\' OR branch_name LIKE \'%BRIG%\' or branch_name like \'%MAPLE - MYSURU%\') AND (account_name LIKE \'%SNITCH - WH - YE%\' or account_name LIKE \'%SNITCH - WH - EMI%\' or account_name ilike \'%WH - NORTH%\') THEN \'WH-STORE\' WHEN (branch_name LIKE \'%COCO%\' OR branch_name LIKE \'%FOCO%\' OR branch_name LIKE \'%COFO%\' OR branch_name LIKE \'%JAYAN%\' OR branch_name LIKE \'%BRIG%\') AND (account_name LIKE \'%COCO%\' OR account_name LIKE \'%FOCO%\' OR account_name LIKE \'%COFO%\' OR account_name LIKE \'%JAYAN%\' OR account_name LIKE \'%BRIG%\') THEN \'STORE-STORE\' ELSE \'OTHERS\' END AS ORIGIN, branch_name AS to_party, account_name AS from_party, BILL_NO, DOC_TYPE, QUANTITY AS TOTAL_QUANTITY, VOUCH_NO, TRY_TO_DATE(BILL_DATE, \'DD/MM/YYYY\') AS BILL_DATE, TOTAL_TAX, AGENT_NAME, GRN_NUMBER, GRN_PREFIX, NET_AMOUNT, VOUCH_CODE, TRY_TO_DATE(VOUCH_DATE, \'DD/MM/YYYY\') AS VOUCH_DATE, ACTION_CODE, BRANCH_CODE, ACCOUNT_CODE, GROSS_AMOUNT, CURRENCY_NAME, DOC_TYPE_DESC, TAX_REGION_NAME, CASE WHEN UPPER(COALESCE(LISTITEMS.value:AddlItemCode::STRING,LISTITEMS.value:ItemCode::STRING )) like \'4C%\' then UPPER(COALESCE(LISTITEMS.value:AddlItemCode::STRING,LISTITEMS.value:ItemCode::STRING )) WHEN UPPER(UPPER(COALESCE(LISTITEMS.value:AddlItemCode::STRING,LISTITEMS.value:ItemCode::STRING ))) LIKE \'%T-SHIRT%\' OR UPPER(UPPER(COALESCE(LISTITEMS.value:AddlItemCode::STRING,LISTITEMS.value:ItemCode::STRING ))) LIKE \'%CO-ORDS%\' THEN replace(replace(UPPER(UPPER(COALESCE(LISTITEMS.value:AddlItemCode::STRING,LISTITEMS.value:ItemCode::STRING ))),\'T-SHIRT-\',\'\'),\'CO-ORDS-\',\'\') WHEN REGEXP_COUNT(UPPER(COALESCE(LISTITEMS.value:AddlItemCode::STRING,LISTITEMS.value:ItemCode::STRING )), \'-\') = 3 THEN SPLIT_PART(UPPER(COALESCE(LISTITEMS.value:AddlItemCode::STRING,LISTITEMS.value:ItemCode::STRING )), \'-\', 1)||\'-\'|| SPLIT_PART(UPPER(COALESCE(LISTITEMS.value:AddlItemCode::STRING,LISTITEMS.value:ItemCode::STRING )), \'-\', 2)||\'-\'||SPLIT_PART(UPPER(COALESCE(LISTITEMS.value:AddlItemCode::STRING,LISTITEMS.value:ItemCode::STRING )), \'-\', 4) ELSE UPPER(COALESCE(LISTITEMS.value:AddlItemCode::STRING,LISTITEMS.value:ItemCode::STRING )) END AS SKU_DUMMY, LISTITEMS.value:CD::NUMBER AS CD, LISTITEMS.value:CD_Per::NUMBER AS CD_Per, LISTITEMS.value:CF_1::NUMBER AS CF_1, LISTITEMS.value:CF_2::NUMBER AS CF_2, LISTITEMS.value:CF_3::NUMBER AS CF_3, LISTITEMS.value:Gross_Pur_Amt::NUMBER AS Gross_Pur_Amt, LISTITEMS.value:HSN_Code::STRING AS HSN_Code, LISTITEMS.value:Item_MRP::NUMBER AS Item_MRP, LISTITEMS.value:Item_Pur_Rate::NUMBER AS Item_Pur_Rate, LISTITEMS.value:Item_Sale_Rate::NUMBER AS Item_Sale_Rate, LISTITEMS.value:Lot_Code::STRING AS Lot_Code, LISTITEMS.value:Lot_MRP::NUMBER AS Lot_MRP, LISTITEMS.value:Lot_Number::STRING AS Lot_Number, LISTITEMS.value:PackName::STRING AS PackName, LISTITEMS.value:Quantity::NUMBER AS Item_Quantity, LISTITEMS.value:Rate::NUMBER AS Item_Rate, LISTITEMS.value:Tax_Amt_1::NUMBER AS Tax_Amt_1, LISTITEMS.value:Tax_Amt_3::NUMBER AS Tax_Amt_3, LISTITEMS.value:Tax_P_1::NUMBER AS Tax_P_1, LISTITEMS.value:Tax_P_2::NUMBER AS Tax_P_2, LISTITEMS.value:Tax_P_3::NUMBER AS Tax_P_3 FROM snitch_db.maplemonk.logicstream_get_stock_transfer_in, LATERAL FLATTEN(INPUT => LISTITEMS) AS LISTITEMS ) select CASE WHEN d.sku_dummy like \'8%\' THEN e1.sku ELSE d.sku_dummy END AS SKU, d.* from final d left join snitch_db.maplemonk.ean_to_sku_mapping e1 on d.sku_dummy = e1.ean ;",
